<template><div v-loading="loading"><el-alert title="追溯数据来自该订单的实际收货、质检与退货记录；不合格或未检完的批次进入质量追溯状态。" type="info" :closable="false"/><el-tabs v-model="kind" @tab-click="changeKind"><el-tab-pane name="receipts" label="收货历史"/><el-tab-pane name="inspections" label="质检历史"/><el-tab-pane name="returns" label="退货历史"/></el-tabs><el-table :data="items" border empty-text="该订单暂无对应记录"><el-table-column v-for="c in columns" :key="c[0]" :prop="c[0]" :label="c[1]" min-width="130"/></el-table><el-pagination layout="total,prev,pager,next" :total="total" :page-size="10" :current-page.sync="page" @current-change="load"/></div></template>
<script>
import {api} from '../api/client';
export default {props:{orderId:String},data:()=>({kind:'receipts',items:[],page:1,total:0,loading:false}),computed:{columns(){return {receipts:[['receipt_no','收货单号'],['material_code','物料编码'],['received_date','收货日期'],['received_quantity','收货数量'],['accepted_quantity','合格数量'],['rejected_quantity','不合格数量'],['status','状态']],inspections:[['inspection_no','质检单号'],['receipt_no','收货单号'],['inspected_quantity','检验数量'],['accepted_quantity','合格数量'],['rejected_quantity','不合格数量'],['rework_quantity','返修数量'],['defect_description','缺陷说明'],['inspected_at','检验时间']],returns:[['return_no','退货单号'],['receipt_no','收货单号'],['material_code','物料编码'],['quantity','数量'],['reason','原因'],['status','状态']]}[this.kind];}},created(){this.load();},methods:{changeKind(){this.page=1;this.load();},async load(){this.loading=true;try{const r=(await api.get(`/orders/${this.orderId}/trace`,{params:{kind:this.kind,page:this.page,page_size:10}})).data;this.items=r.items;this.total=r.total;}catch(e){this.$message.error(e.response?.data?.detail||'追溯加载失败');}finally{this.loading=false;}}}};
</script>
